"use client";

import "../../styles/teum-base.css";
import "../../styles/components/toast.css";
import { Toaster as SonnerToaster, toast as sonnerToast } from "sonner";
import type { ExternalToast, ToasterProps } from "sonner";
import type { ReactNode } from "react";

export type ToastId = string | number;
export type ToastMessage = ReactNode | (() => ReactNode);
export type ToastOptions = ExternalToast;

export type ToastApi = {
  (message: ToastMessage, options?: ToastOptions): ToastId;
  success: (message: ToastMessage, options?: ToastOptions) => ToastId;
  info: (message: ToastMessage, options?: ToastOptions) => ToastId;
  warning: (message: ToastMessage, options?: ToastOptions) => ToastId;
  error: (message: ToastMessage, options?: ToastOptions) => ToastId;
  loading: (message: ToastMessage, options?: ToastOptions) => ToastId;
  dismiss: (id?: ToastId) => ToastId;
};

const toastClassNames = {
  toast: "teum-toast",
  content: "teum-toast__content",
  title: "teum-toast__title",
  description: "teum-toast__description",
  actionButton: "teum-toast__action",
  closeButton: "teum-toast__close",
};

export function Toaster({
  className,
  position = "bottom-center",
  visibleToasts = 1,
  expand = false,
  closeButton = true,
  duration = 4000,
  gap = 8,
  offset = 20,
  toastOptions,
  ...props
}: ToasterProps) {
  return (
    <SonnerToaster
      {...props}
      className={["teum-toaster", className].filter(Boolean).join(" ")}
      position={position}
      visibleToasts={visibleToasts}
      expand={expand}
      closeButton={closeButton}
      duration={duration}
      gap={gap}
      offset={offset}
      style={{ "--width": "326px", ...props.style } as ToasterProps["style"]}
      toastOptions={{
        ...toastOptions,
        unstyled: true,
        classNames: {
          ...toastClassNames,
          ...toastOptions?.classNames,
        },
      }}
    />
  );
}

export const toast: ToastApi = Object.assign(
  (message: ToastMessage, options?: ToastOptions) => sonnerToast(message, options),
  {
    success: (message: ToastMessage, options?: ToastOptions) => sonnerToast.success(message, options),
    info: (message: ToastMessage, options?: ToastOptions) => sonnerToast.info(message, options),
    warning: (message: ToastMessage, options?: ToastOptions) => sonnerToast.warning(message, options),
    error: (message: ToastMessage, options?: ToastOptions) => sonnerToast.error(message, options),
    loading: (message: ToastMessage, options?: ToastOptions) => sonnerToast.loading(message, options),
    dismiss: (id?: ToastId) => sonnerToast.dismiss(id),
  },
);

/* Generated from src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-toaster { --width: 326px; z-index: var(--teum-layer-toast); }

.teum-toast { position: relative; display: flex; width: 326px; max-width: calc(100vw - 32px); min-height: 52px; align-items: center; gap: 10px; padding: 10px 40px 10px 12px; border: 1px solid var(--teum-border-subtle); border-radius: 8px; background: var(--teum-bg-flyout); color: var(--teum-ink); box-shadow: var(--teum-shadow-flyout); font-family: inherit; }

.teum-toast__content { display: grid; flex: 1; gap: 2px; }

.teum-toast__title { font-size: 13.5px; font-weight: 580; }

.teum-toast__description { color: var(--teum-ink-secondary); font-size: 12px; }

.teum-toast__action { height: 28px; padding: 0 8px; border: 1px solid var(--teum-border); border-radius: 5px; background: var(--teum-control-surface); color: var(--teum-ink); font-size: 12px; font-weight: 550; }

.teum-toast__close { position: absolute; top: 8px; right: 8px; display: grid; width: 22px; height: 22px; padding: 0; place-items: center; border: 0; border-radius: 4px; background: transparent; color: var(--teum-fg-subtle); }

@media (forced-colors: active) {
.teum-toast { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }
}
}
